"bugs\": {\n    \"url\": \"https://github.com/shaobeichen/dsh-pocket/issues\"\n  },\n  \"homepage\": \"https://github.com/shaobeichen/dsh-pocket\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"version\": \"2.12.0\"\n}\n"
